func newTestCacheDB(t *testing.T) *CacheDB {
	t.Helper()
	path := filepath.Join(t.TempDir(), "cache.db")
	db, err := NewCacheDB(path)
	if err != nil {
		t.Fatalf("open CacheDB: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	return db
}

