func TestFreshSchemaHasFailCount(t *testing.T) {
	cache := newTestCacheDB(t)
	rows, err := cache.SQL().Query(
		"PRAGMA table_info(decommissioned_repos)")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var cols []string
	for rows.Next() {
		var cid int64
		var name, typ string
		var notnull int64
		var dflt any
		var pk int64
		if err := rows.Scan(&cid, &name, &typ, &notnull, &dflt, &pk); err != nil {
			t.Fatal(err)
		}
		cols = append(cols, name)
	}
	for _, c := range cols {
		if c == "fail_count" {
			return
		}
	}
	t.Fatalf("fresh schema lacks fail_count: %v", cols)
}

func TestMigrationMarksPreV08RowsConfirmed(t *testing.T) {
	// A pre-v0.08 cache: decommissioned_repos WITHOUT fail_count.
	path := filepath.Join(t.TempDir(), "cache.db")
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	legacy, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, stmt := range []string{
		"CREATE TABLE decommissioned_repos ( url TEXT PRIMARY KEY," +
			" reason TEXT, decommissioned_at TIMESTAMP)",
		"INSERT INTO decommissioned_repos VALUES " +
			"('https://github.com/dead/repo', '404 Not Found', '2025-01-01')",
	} {
		if _, err := legacy.SQL().Exec(stmt); err != nil {
			t.Fatal(err)
		}
	}
	if err := legacy.Close(); err != nil {
		t.Fatal(err)
	}
	// Opening through CacheDB runs the migration; the pre-existing row
	// was 404'd in earlier sessions, so it must be CONFIRMED dead now.
	cache, err := NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	defer cache.Close()
	if !cache.IsDeadLink("https://github.com/dead/repo", 0) {
		t.Fatal("legacy row not confirmed after migration")
	}
	if !cache.GetDeadURLSet(0)["https://github.com/dead/repo"] {
		t.Fatal("legacy row missing from the dead set")
	}
}

func TestRecord404CountsAcrossSessions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cache.db")
	url := "https://github.com/gone/forever"
	var counts []int
	for i := 0; i < DeadLinkThreshold; i++ {
		cache, err := NewCacheDB(path) // NEW session, same DB file
		if err != nil {
			t.Fatal(err)
		}
		counts = append(counts, cache.Record404(url, "404 Not Found"))
		cache.Close()
	}
	if !reflect.DeepEqual(counts, []int{1, 2, 3}) {
		t.Fatalf("counts = %v; want [1 2 3]", counts)
	}
	cache, err := NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	defer cache.Close()
	if counts[len(counts)-1] != DeadLinkThreshold {
		t.Fatalf("last count = %d", counts[len(counts)-1])
	}
	if !cache.IsDeadLink(url, 0) {
		t.Fatal("url not confirmed dead after 3 strikes")
	}
}

func TestUnconfirmedEntriesAreNotDead(t *testing.T) {
	cache := newTestCacheDB(t)
	url := "https://github.com/flaky/repo"
	cache.Record404(url, "404")
	cache.Record404(url, "404") // 2 of 3 — still retriable
	if cache.IsDeadLink(url, 0) {
		t.Fatal("2-of-3 entry read as dead")
	}
	if cache.GetDeadURLSet(0)[links.NormalizeURL(url)] {
		t.Fatal("unconfirmed entry in the dead set")
	}
}

func TestDeadSetOnlyContainsConfirmed(t *testing.T) {
	cache := newTestCacheDB(t)
	deadURL := "https://github.com/dead/repo"
	liveURL := "https://github.com/ok/repo"
	for i := 0; i < DeadLinkThreshold; i++ {
		cache.Record404(deadURL, "404")
	}
	cache.Record404(liveURL, "404") // 1 attempt — unconfirmed
	dead := cache.GetDeadURLSet(0)
	if !dead[links.NormalizeURL(deadURL)] {
		t.Fatal("confirmed url missing from dead set")
	}
	if dead[links.NormalizeURL(liveURL)] {
		t.Fatal("unconfirmed url in the dead set")
	}
}

func TestResetDeadLinksClearsEverything(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cache.db")
	url := "https://github.com/private/now-public"
	cache, err := NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < DeadLinkThreshold; i++ {
		cache.Record404(url, "404")
	}
	if !cache.IsDeadLink(url, 0) {
		t.Fatal("not dead before reset")
	}
	removed := cache.ResetDeadLinks("")
	cache.Close()
	if removed < 1 {
		t.Fatalf("removed = %d", removed)
	}
	cache, err = NewCacheDB(path) // persists across sessions
	if err != nil {
		t.Fatal(err)
	}
	defer cache.Close()
	if cache.IsDeadLink(url, 0) {
		t.Fatal("still dead after reset")
	}
	if len(cache.GetDeadURLSet(0)) != 0 {
		t.Fatal("dead set not empty after reset")
	}
}

func TestResetDeadLinksSingleURL(t *testing.T) {
	cache := newTestCacheDB(t)
	keep := "https://github.com/dead/one"
	drop := "https://github.com/dead/two"
	for _, u := range []string{keep, drop} {
		for i := 0; i < DeadLinkThreshold; i++ {
			cache.Record404(u, "404")
		}
	}
	if removed := cache.ResetDeadLinks(drop); removed != 1 {
		t.Fatalf("removed = %d; want 1", removed)
	}
	if !cache.IsDeadLink(keep, 0) {
		t.Fatal("keep url died")
	}
	if cache.IsDeadLink(drop, 0) {
		t.Fatal("drop url survived")
	}
}

func TestGetAllDecommissionedShapeUnchanged(t *testing.T) {
	cache := newTestCacheDB(t)
	cache.Record404("https://github.com/dead/repo", "404 Not Found")
	rows := cache.GetAllDecommissioned()
	if len(rows) != 1 {
		t.Fatalf("rows = %d; want 1", len(rows))
	}
	if rows[0].URL != "https://github.com/dead/repo" ||
		rows[0].Error != "404 Not Found" {
		t.Fatalf("legacy (url, reason) shape changed: %+v", rows[0])
	}
}

func TestThresholdIsThree(t *testing.T) {
	if DeadLinkThreshold != 3 {
		t.Fatalf("DEAD_LINK_THRESHOLD = %d; want 3", DeadLinkThreshold)
	}
}

