func TestThresholdIsConfigurable(t *testing.T) {
	cases := []struct {
		cfg  map[string]any
		want int
	}{
		{map[string]any{}, 3},
		{map[string]any{"notfound_strike_threshold": 5}, 5},
		{map[string]any{"notfound_strike_threshold": 0}, 2},
		{map[string]any{"notfound_strike_threshold": "bogus"}, 3},
		{map[string]any{"notfound_strike_threshold": "7"}, 7},
		{map[string]any{"notfound_strike_threshold": 2.9}, 2},
	}
	for _, tc := range cases {
		if got := DeadLinkThresholdFromConfig(tc.cfg); got != tc.want {
			t.Errorf("threshold(%v) = %d; want %d", tc.cfg, got, tc.want)
		}
	}
}

func TestThresholdParameterSteersConfirmation(t *testing.T) {
	cache := newTestCacheDB(t)
	url := "https://github.com/patient/repo"
	for i := 0; i < 3; i++ {
		cache.Record404(url, "404") // 3 attempts
	}
	if !cache.IsDeadLink(url, 0) {
		t.Fatal("dead at default threshold 3")
	}
	if cache.IsDeadLink(url, 5) {
		t.Fatal("dead at configured threshold 5")
	}
	if len(cache.GetDeadURLSet(5)) != 0 {
		t.Fatal("dead set at 5 not empty")
	}
	if len(cache.GetDeadURLs(5)) != 0 {
		t.Fatal("dead urls at 5 not empty")
	}
}

func TestSuccessResetsTheCounter(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cache.db")
	url := "https://github.com/back/from-the-dead"
	cache, err := NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	cache.Record404(url, "404")
	cache.Record404(url, "404") // 2 of 3
	cache.ResetDeadLinks(url)   // SUCCESS — counter fresh
	cache.Close()
	cache, err = NewCacheDB(path) // next session
	if err != nil {
		t.Fatal(err)
	}
	defer cache.Close()
	if got := cache.Record404(url, "404"); got != 1 {
		t.Fatalf("record after reset = %d; want 1 (started over)", got)
	}
	if cache.IsDeadLink(url, 0) {
		t.Fatal("dead after reset + one strike")
	}
}

func TestV007StrikeTableMigrates(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cache.db")
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	legacy, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, stmt := range []string{
		"CREATE TABLE notfound_strikes ( url TEXT PRIMARY KEY," +
			" strikes INTEGER, first_seen TIMESTAMP, last_seen TIMESTAMP)",
		"INSERT INTO notfound_strikes VALUES " +
			"('https://github.com/a/gone', 2, '2025-01-01', '2025-01-02')",
		"INSERT INTO notfound_strikes VALUES " +
			"('https://github.com/b/gone', 3, '2025-01-01', '2025-01-02')",
		"CREATE TABLE decommissioned_repos ( url TEXT PRIMARY KEY," +
			" reason TEXT, decommissioned_at TIMESTAMP," +
			" fail_count INTEGER NOT NULL DEFAULT 3)",
		"INSERT INTO decommissioned_repos VALUES " +
			"('https://github.com/b/gone', '404 Not Found', '2025-01-01', 1)",
	} {
		if _, err := legacy.SQL().Exec(stmt); err != nil {
			t.Fatal(err)
		}
	}
	if err := legacy.Close(); err != nil {
		t.Fatal(err)
	}
	cache, err := NewCacheDB(path) // migration runs on open
	if err != nil {
		t.Fatal(err)
	}
	defer cache.Close()
	stats := map[string]int64{}
	for _, r := range cache.GetQuarantineStats() {
		stats[r.URL] = r.FailCount
	}
	if stats["https://github.com/a/gone"] != 2 {
		t.Fatalf("a/gone = %d; want 2", stats["https://github.com/a/gone"])
	}
	if stats["https://github.com/b/gone"] != 3 {
		t.Fatalf("b/gone = %d; want 3 (MAX kept)", stats["https://github.com/b/gone"])
	}
	// old table dropped — one system, one table
	var left int
	if err := cache.SQL().QueryRow(
		"SELECT COUNT(*) FROM sqlite_master " +
			"WHERE type='table' AND name='notfound_strikes'").Scan(&left); err != nil {
		t.Fatal(err)
	}
	if left != 0 {
		t.Fatal("notfound_strikes survived the migration")
	}
}

func TestQuarantineStatsShowsInProgressRows(t *testing.T) {
	cache := newTestCacheDB(t)
	live := "https://github.com/still/there"
	dead := "https://github.com/long/gone"
	cache.Record404(live, "404") // 1 attempt — in progress
	for i := 0; i < 3; i++ {
		cache.Record404(dead, "404") // confirmed
	}
	rows := cache.GetQuarantineStats()
	urls := map[string]bool{}
	for _, r := range rows {
		urls[r.URL] = true
	}
	if len(urls) != 2 || !urls[live] || !urls[dead] {
		t.Fatalf("stats urls = %v; want both (in-progress AND confirmed)", urls)
	}
	// most-strikes first
	if rows[0].URL != dead {
		t.Fatalf("first row = %s; want %s (most-strikes first)", rows[0].URL, dead)
	}
}

