// test_retrycry.py: TestFailedRowsTruth
// ---------------------------------------------------------------------------

var retrycryRows = []FailedRow{
	{"https://example.com/walled-article", "failed Phase 3 verification"},
	{"https://github.com/owner/stale", "timeout"},
	{"https://github.com/owner/missing", "gave up"},
	{"", "a null-url row is nobody's retry"},
}

func TestWebsiteRowsAreNeverTheReposQueue(t *testing.T) {
	stale, missing, websites := FailedRowsTruth(retrycryRows, nil)
	if !reflect.DeepEqual(websites,
		[]string{"https://example.com/walled-article"}) {
		t.Fatalf("websites = %v", websites)
	}
	for _, u := range append(append([]string{}, stale...), missing...) {
		if u == "https://example.com/walled-article" {
			t.Fatal("website row leaked into a github bucket")
		}
	}
}

func TestProbeSeparatesStaleFromMissing(t *testing.T) {
	stale, missing, websites := FailedRowsTruth(retrycryRows,
		func(u string) bool { return stringsContains(u, "stale") })
	if !reflect.DeepEqual(stale, []string{"https://github.com/owner/stale"}) {
		t.Fatalf("stale = %v", stale)
	}
	if !reflect.DeepEqual(missing, []string{"https://github.com/owner/missing"}) {
		t.Fatalf("missing = %v", missing)
	}
	if !reflect.DeepEqual(websites,
		[]string{"https://example.com/walled-article"}) {
		t.Fatalf("websites = %v", websites)
	}
}

func TestNoProbeKeepsTheOldLoudBehavior(t *testing.T) {
	// A broken/absent vault index must not silence a genuine cry —
	// every github row reads as missing (the old count's behavior).
	stale, missing, _ := FailedRowsTruth(retrycryRows, nil)
	if len(stale) != 0 {
		t.Fatalf("stale = %v; want empty", stale)
	}
	sortStrings(missing) // the Python suite sorts before asserting
	want := []string{"https://github.com/owner/missing",
		"https://github.com/owner/stale"}
	if !reflect.DeepEqual(missing, want) {
		t.Fatalf("missing = %v; want %v", missing, want)
	}
}

func TestNullURLsAreSkippedEntirely(t *testing.T) {
	stale, missing, websites := FailedRowsTruth(retrycryRows, nil)
	for _, bucket := range [][]string{stale, missing, websites} {
		for _, u := range bucket {
			if u == "" {
				t.Fatal("an empty url survived into a bucket")
			}
		}
	}
}

// The legacy-shapes leg (None / dict rows) is structurally absent in
// Go's typed rows; the buckets over the representable inputs are what
// the pure golden pins (TestCachereposPureGolden).
func TestEmptyRowsDegradeQuietly(t *testing.T) {
	stale, missing, websites := FailedRowsTruth(nil, nil)
	if len(stale)+len(missing)+len(websites) != 0 {
		t.Fatal("nil rows produced buckets")
	}
}

// ---------------------------------------------------------------------------
// test_retrycry.py: TestRetryQueueHonesty
// ---------------------------------------------------------------------------

func TestAddFailedNeverStacks(t *testing.T) {
	// Three failures of the same URL = ONE unresolved row.
	cache := newTestCacheDB(t)
	for i := 0; i < 3; i++ {
		cache.AddFailed("https://github.com/o/r", fmt.Sprintf("failure %d", i))
	}
	rows := cache.GetFailedURLs()
	if len(rows) != 1 {
		t.Fatalf("rows = %d; want 1 (no stacking)", len(rows))
	}
	if rows[0].Error != "failure 2" { // the fresher error wins
		t.Fatalf("error = %q; want failure 2", rows[0].Error)
	}
}

func TestAddFailedKeysByTheNormalizedURL(t *testing.T) {
	// Trailing-slash and scheme drift land on the SAME row.
	cache := newTestCacheDB(t)
	cache.AddFailed("https://github.com/o/r", "one")
	cache.AddFailed("https://github.com/o/r/", "two")
	if got := cache.GetFailedCount(); got != 1 {
		t.Fatalf("count = %d; want 1 (normalized keying)", got)
	}
}

func TestResolveMatchesBothSpellings(t *testing.T) {
	// A legacy-shaped row, written the old way (raw string), resolves
	// under a trailing-slash spelling.
	cache := newTestCacheDB(t)
	cache.Lock()
	_, err := cache.SQL().Exec(
		"INSERT INTO failed_repos (url, error, failed_at, "+
			"retry_count) VALUES (?, ?, ?, 0)",
		"https://github.com/Owner/Repo", "legacy row", "2026-01-01T00:00:00")
	cache.Unlock()
	if err != nil {
		t.Fatal(err)
	}
	cache.MarkFailedResolved("https://github.com/Owner/Repo/")
	if got := cache.GetFailedCount(); got != 0 {
		t.Fatalf("count = %d; want 0 (both spellings resolve)", got)
	}
}

func TestResolveFailedURLsSettlesAWholeList(t *testing.T) {
	cache := newTestCacheDB(t)
	cache.AddFailed("https://github.com/o/stale", "timeout")
	cache.AddFailed("https://example.com/walled", "phase 3")
	cache.AddFailed("https://github.com/o/missing", "gave up")
	flipped := cache.ResolveFailedURLs([]string{
		"https://github.com/o/stale", "https://example.com/walled"})
	if flipped != 2 {
		t.Fatalf("flipped = %d; want 2", flipped)
	}
	var urls []string
	for _, r := range cache.GetFailedURLs() {
		urls = append(urls, r.URL)
	}
	if !reflect.DeepEqual(urls, []string{"https://github.com/o/missing"}) {
		t.Fatalf("after bulk = %v", urls)
	}
	if got := cache.GetFailedCount(); got != 1 {
		t.Fatalf("count = %d; want 1", got)
	}
}

func TestResolvedHistoryIsNeverTouchedByAdd(t *testing.T) {
	// add_failed updates only the UNRESOLVED row — the resolved history
	// of a URL stays as the record.
	cache := newTestCacheDB(t)
	cache.AddFailed("https://github.com/o/r", "first")
	cache.MarkFailedResolved("https://github.com/o/r")
	cache.AddFailed("https://github.com/o/r", "second")
	cache.RLock()
	rows, err := cache.SQL().Query(
		"SELECT url, error, resolved FROM failed_repos ORDER BY id")
	cache.RUnlock()
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var got [][]any
	for rows.Next() {
		var u, e string
		var resolved int64
		if err := rows.Scan(&u, &e, &resolved); err != nil {
			t.Fatal(err)
		}
		got = append(got, []any{u, e, resolved})
	}
	if len(got) != 2 {
		t.Fatalf("rows = %d; want 2 (fresh cry + history)", len(got))
	}
	var resolvedFlags []int64
	var errors []string
	for _, r := range got {
		resolvedFlags = append(resolvedFlags, r[2].(int64))
		errors = append(errors, r[1].(string))
	}
	sortInt64(resolvedFlags)
	if !reflect.DeepEqual(resolvedFlags, []int64{0, 1}) {
		t.Fatalf("resolved flags = %v; want [0 1]", resolvedFlags)
	}
	sortStrings(errors)
	if !reflect.DeepEqual(errors, []string{"first", "second"}) {
		t.Fatalf("errors = %v", errors)
	}
}

