func TestSettleAndUnsettleRoundTrip(t *testing.T) {
	db := newSettledCacheDB(t)
	if _, err := db.SettleExistingRepos(nil); err != nil {
		t.Fatal(err)
	}
	// the owner's verdict door: settle_repos
	added, err := db.SettleRepos([]string{"https://github.com/owner/fresh"})
	if err != nil {
		t.Fatal(err)
	}
	if added != 1 {
		t.Fatalf("added = %d; want 1", added)
	}
	if !db.IsRepoSettled("https://github.com/owner/fresh") {
		t.Fatal("fresh not settled")
	}
	if got := db.SettledReposCount(); got != 4 {
		t.Fatalf("count = %d; want 4", got)
	}
	// idempotent
	if added, err = db.SettleRepos(
		[]string{"https://github.com/owner/fresh"}); err != nil || added != 0 {
		t.Fatalf("second settle = %d/%v; want 0", added, err)
	}
	// the ♻️ door back: unsettle_repo
	if !db.UnsettleRepo("https://github.com/owner/fresh") {
		t.Fatal("unsettle = false")
	}
	if db.IsRepoSettled("https://github.com/owner/fresh") {
		t.Fatal("still settled after unsettle")
	}
	if db.UnsettleRepo("https://github.com/owner/fresh") {
		t.Fatal("second unsettle = true (honest False wanted)")
	}
}

