type cachereposPure struct {
	Schema    int `json:"schema"`
	Constants struct {
		DeadLinkThreshold int64  `json:"DEAD_LINK_THRESHOLD"`
		ReposSettledKey   string `json:"REPOS_SETTLED_META_KEY"`
	} `json:"constants"`
	FailedRowsTruth struct {
		NoProbe bucketsJSON `json:"no_probe"`
		Probe   bucketsJSON `json:"probe"`
		Legacy  bucketsJSON `json:"legacy_shapes"`
		Empty   bucketsJSON `json:"empty"`
	} `json:"failed_rows_truth"`
	DeadLinkThreshold [][]any `json:"dead_link_threshold"`
}

type bucketsJSON struct {
	Stale    []string `json:"stale"`
	Missing  []string `json:"missing"`
	Websites []string `json:"websites"`
}

func TestCachereposPureGolden(t *testing.T) {
	var g cachereposPure
	decodeGolden(t, "cacherepos_pure.golden.json", &g)

	if DeadLinkThreshold != int(g.Constants.DeadLinkThreshold) ||
		ReposSettledMetaKey != g.Constants.ReposSettledKey {
		t.Fatalf("constants drifted: %+v", g.Constants)
	}

	// failed_rows_truth — the test_retrycry ROWS.
	check := func(name string, stale, missing, websites []string,
		want bucketsJSON) {
		t.Helper()
		if !strSlicesEqual(stale, want.Stale) ||
			!strSlicesEqual(missing, want.Missing) ||
			!strSlicesEqual(websites, want.Websites) {
			t.Errorf("%s: got (%v/%v/%v); golden (%v/%v/%v)", name,
				stale, missing, websites,
				want.Stale, want.Missing, want.Websites)
		}
	}
	stale, missing, websites := FailedRowsTruth(retrycryRows, nil)
	check("no_probe", stale, missing, websites, g.FailedRowsTruth.NoProbe)
	stale, missing, websites = FailedRowsTruth(retrycryRows,
		func(u string) bool { return stringsContains(u, "stale") })
	check("probe", stale, missing, websites, g.FailedRowsTruth.Probe)
	stale, missing, websites = FailedRowsTruth(nil, nil)
	check("empty", stale, missing, websites, g.FailedRowsTruth.Empty)
	// The legacy-shapes probe: the representable equivalent (a dict row
	// is a FailedRow with the url; a None row is absent).
	legacyRows := []FailedRow{
		{"https://example.com/x", ""},
		{"https://github.com/o/r", "e"},
	}
	stale, missing, websites = FailedRowsTruth(legacyRows, nil)
	check("legacy_shapes", stale, missing, websites,
		g.FailedRowsTruth.Legacy)

	// The threshold clamp battery.
	for _, tc := range g.DeadLinkThreshold {
		if len(tc) != 2 {
			t.Fatalf("threshold case = %v", tc)
		}
		cfg, ok := tc[0].(map[string]any)
		if !ok {
			t.Fatalf("threshold case cfg = %v", tc[0])
		}
		want := pyInt(tc[1])
		if got := DeadLinkThresholdFromConfig(cfg); int64(got) != want {
			t.Errorf("threshold(%v) = %d; golden %d", cfg, got, want)
		}
	}
}

