func TestCachereposBehaviorGolden(t *testing.T) {
	var g cachereposBehavior
	decodeGolden(t, "cacherepos_behavior.golden.json", &g)

	// -- the pre-v0.08 migration --
	path := filepath.Join(t.TempDir(), "cache.db")
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	legacy, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, stmt := range g.Probes.MigrationPreV08.LegacyStatements {
		if _, err := legacy.SQL().Exec(stmt); err != nil {
			t.Fatal(err)
		}
	}
	legacy.Close()
	cache, err := NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	if got := cache.IsDeadLink("https://github.com/dead/repo", 0); got != g.Probes.MigrationPreV08.IsDeadLink {
		t.Errorf("pre-v08 is_dead_link = %v; golden %v", got,
			g.Probes.MigrationPreV08.IsDeadLink)
	}
	var deadSet []string
	for u := range cache.GetDeadURLSet(0) {
		deadSet = append(deadSet, u)
	}
	sortStrings(deadSet)
	if !reflect.DeepEqual(deadSet, g.Probes.MigrationPreV08.DeadSet) {
		t.Errorf("pre-v08 dead set = %v; golden %v", deadSet,
			g.Probes.MigrationPreV08.DeadSet)
	}
	cache.Close()

	// -- the v0.07 strikes migration --
	path = filepath.Join(t.TempDir(), "cache.db")
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	legacy, err = Open(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, stmt := range g.Probes.MigrationV07.LegacyStatements {
		if _, err := legacy.SQL().Exec(stmt); err != nil {
			t.Fatal(err)
		}
	}
	legacy.Close()
	cache, err = NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	stats := map[string]int64{}
	for _, r := range cache.GetQuarantineStats() {
		stats[r.URL] = r.FailCount
	}
	if !reflect.DeepEqual(stats, g.Probes.MigrationV07.Stats) {
		t.Errorf("v07 stats = %v; golden %v", stats,
			g.Probes.MigrationV07.Stats)
	}
	var left int64
	if err := cache.SQL().QueryRow(
		"SELECT COUNT(*) FROM sqlite_master " +
			"WHERE type='table' AND name='notfound_strikes'").Scan(&left); err != nil {
		t.Fatal(err)
	}
	if left != g.Probes.MigrationV07.OldTableLeft {
		t.Errorf("old table left = %d; golden %d", left,
			g.Probes.MigrationV07.OldTableLeft)
	}
	cache.Close()

	// -- THE SETTLEMENT --
	db := newSettledCacheDB(t)
	se1, err := db.SettleExistingRepos(nil)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleReposMap(se1),
		normAnyMap(g.Probes.SettleExistingRepos.First)) {
		t.Errorf("settle first = %v; golden %v", settleReposMap(se1),
			g.Probes.SettleExistingRepos.First)
	}
	se2, err := db.SettleExistingRepos([]string{
		"https://github.com/owner/brandnew"})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(settleReposMap(se2),
		normAnyMap(g.Probes.SettleExistingRepos.SecondAfterNew)) {
		t.Errorf("settle second = %v; golden %v", settleReposMap(se2),
			g.Probes.SettleExistingRepos.SecondAfterNew)
	}
	if got := db.IsRepoSettled(
		"https://github.com/owner/brandnew"); got !=
		g.Probes.SettleExistingRepos.BrandnewSettled {
		t.Errorf("brandnew settled = %v; golden %v", got,
			g.Probes.SettleExistingRepos.BrandnewSettled)
	}
	if got := db.SettledReposCount(); int64(got) !=
		g.Probes.SettleExistingRepos.SettledCount {
		t.Errorf("settled count = %d; golden %d", got,
			g.Probes.SettleExistingRepos.SettledCount)
	}
	var settledSet []string
	for u := range db.GetSettledRepoSet() {
		settledSet = append(settledSet, u)
	}
	sortStrings(settledSet)
	if !reflect.DeepEqual(settledSet, g.Probes.SettleExistingRepos.SettledSet) {
		t.Errorf("settled set = %v; golden %v", settledSet,
			g.Probes.SettleExistingRepos.SettledSet)
	}
	for u, want := range g.Probes.SettleExistingRepos.IsSettled {
		if got := db.IsRepoSettled(u); got != want {
			t.Errorf("is_repo_settled(%s) = %v; golden %v", u, got, want)
		}
	}

	// -- settle_repos / unsettle round trip --
	rt := g.Probes.SettleReposRoundTrip
	added, err := db.SettleRepos([]string{"https://github.com/owner/fresh"})
	if err != nil {
		t.Fatal(err)
	}
	if int64(added) != rt.Added || db.IsRepoSettled(
		"https://github.com/owner/fresh") != rt.IsSettled ||
		int64(db.SettledReposCount()) != rt.CountAfterAdd {
		t.Errorf("settle_repos round trip diverged (added %d)", added)
	}
	added, err = db.SettleRepos([]string{"https://github.com/owner/fresh"})
	if err != nil || int64(added) != rt.Idempotent {
		t.Errorf("idempotent settle = %d/%v; golden %d", added, err,
			rt.Idempotent)
	}
	if got := db.UnsettleRepo("https://github.com/owner/fresh"); got != rt.Unsettle {
		t.Errorf("unsettle = %v; golden %v", got, rt.Unsettle)
	}
	if got := db.IsRepoSettled(
		"https://github.com/owner/fresh"); !got != rt.Unsettled {
		t.Errorf("unsettled = %v; golden %v", got, rt.Unsettled)
	}
	if got := db.UnsettleRepo("https://github.com/owner/fresh"); got != rt.UnsettleAgain {
		t.Errorf("unsettle again = %v; golden %v", got, rt.UnsettleAgain)
	}
	db.SetMeta("k", "v")
	if v := db.GetMeta("k"); v == nil || *v != "v" {
		t.Errorf("meta kv round trip = %v", v)
	}
	if v := db.GetMeta("missing-key"); v != nil {
		t.Errorf("missing meta = %v", v)
	}

	// -- the revive door --
	db = newTestCacheDB(t)
	if _, err := db.SettleExistingRepos([]string{
		"https://github.com/q/dead",
		"https://github.com/q/other-dead",
		"https://github.com/q/alive-and-processed"}); err != nil {
		t.Fatal(err)
	}
	if err := db.AddProcessed(7, "https://github.com/q/alive-and-processed",
		"q", "alive-and-processed", "n.md", "AI"); err != nil {
		t.Fatal(err)
	}
	db.Decommission("https://github.com/q/dead", "404")
	rv := g.Probes.ReviveDoor
	if removed := db.ResetDeadLinks(
		"https://github.com/q/dead"); int64(removed) != rv.Single.Removed {
		t.Errorf("single reset removed = %d; golden %d", removed,
			rv.Single.Removed)
	}
	if db.IsRepoSettled("https://github.com/q/dead") ==
		rv.Single.DeadUnsettled {
		t.Errorf("dead settled after single reset (golden: unsettled=%v)",
			rv.Single.DeadUnsettled)
	}
	if db.IsDecommissioned("https://github.com/q/dead") ==
		rv.Single.NotDecommissioned {
		t.Errorf("decommissioned after single reset")
	}
	db.Decommission("https://github.com/q/other-dead", "404")
	if removed := db.ResetDeadLinks(""); int64(removed) != rv.WholeRemoved {
		t.Errorf("whole reset removed = %d; golden %d", removed,
			rv.WholeRemoved)
	}
	if db.IsRepoSettled("https://github.com/q/other-dead") ==
		rv.OtherDeadUnsettled {
		t.Errorf("other-dead settled after whole reset")
	}
	if got := db.IsRepoSettled(
		"https://github.com/q/alive-and-processed"); got !=
		rv.AliveKeepsSettlement {
		t.Errorf("alive settlement = %v; golden %v", got,
			rv.AliveKeepsSettlement)
	}
	if got := db.SettledReposCount(); int64(got) != rv.SettledCount {
		t.Errorf("revive settled count = %d; golden %d", got, rv.SettledCount)
	}

	// -- record_404 FAILS CLOSED (the acceptance) --
	db = newTestCacheDB(t)
	db.Record404("https://github.com/o/r", "404 Not Found")
	db.Close()
	if got := db.Record404("https://github.com/o/r2",
		"404 Not Found"); int64(got) != pyInt(
		g.Probes.Record404FailClosed.ClosedAnswer) {
		t.Errorf("fail-closed answer = %d; golden %v", got,
			g.Probes.Record404FailClosed.ClosedAnswer)
	}

	// -- the retry queue's laws --
	db = newTestCacheDB(t)
	for i := 0; i < 3; i++ {
		db.AddFailed("https://github.com/o/r", fmt.Sprintf("failure %d", i))
	}
	var stackRows [][]any
	for _, r := range db.GetFailedURLs() {
		stackRows = append(stackRows, []any{r.URL, r.Error})
	}
	if !reflect.DeepEqual(normalizeRows(stackRows),
		normalizeRows(g.Probes.RetryQueue.StackRows)) {
		t.Errorf("stack rows = %v; golden %v", stackRows,
			g.Probes.RetryQueue.StackRows)
	}
	db.AddFailed("https://github.com/o/r2", "one")
	db.AddFailed("https://github.com/o/r2/", "two")
	if got := int64(db.GetFailedCount()); got !=
		g.Probes.RetryQueue.NormalizedKeyCount {
		t.Errorf("normalized key count = %d; golden %d", got,
			g.Probes.RetryQueue.NormalizedKeyCount)
	}
	db.Lock()
	_, err = db.SQL().Exec(
		"INSERT INTO failed_repos (url, error, failed_at, "+
			"retry_count) VALUES (?, ?, ?, 0)",
		"https://github.com/Owner/Repo", "legacy row", "2026-01-01T00:00:00")
	db.Unlock()
	if err != nil {
		t.Fatal(err)
	}
	db.MarkFailedResolved("https://github.com/Owner/Repo/")
	if got := int64(db.GetFailedCount()); got !=
		g.Probes.RetryQueue.LegacyResolved {
		t.Errorf("legacy resolved = %d; golden %d", got,
			g.Probes.RetryQueue.LegacyResolved)
	}
	db.AddFailed("https://github.com/o/stale", "timeout")
	db.AddFailed("https://example.com/walled", "phase 3")
	db.AddFailed("https://github.com/o/missing", "gave up")
	if got := int64(db.ResolveFailedURLs([]string{
		"https://github.com/o/stale",
		"https://example.com/walled"})); got != g.Probes.RetryQueue.BulkFlipped {
		t.Errorf("bulk flipped = %d; golden %d", got,
			g.Probes.RetryQueue.BulkFlipped)
	}
	var afterBulk []string
	for _, r := range db.GetFailedURLs() {
		afterBulk = append(afterBulk, r.URL)
	}
	if !reflect.DeepEqual(afterBulk, g.Probes.RetryQueue.AfterBulk) {
		t.Errorf("after bulk = %v; golden %v", afterBulk,
			g.Probes.RetryQueue.AfterBulk)
	}
	db.AddFailed("https://github.com/o/hist", "first")
	db.MarkFailedResolved("https://github.com/o/hist")
	db.AddFailed("https://github.com/o/hist", "second")
	db.RLock()
	rows, err := db.SQL().Query(
		"SELECT url, error, resolved FROM failed_repos ORDER BY id")
	db.RUnlock()
	if err != nil {
		t.Fatal(err)
	}
	var histRows [][]any
	for rows.Next() {
		var u, e string
		var resolved int64
		if err := rows.Scan(&u, &e, &resolved); err != nil {
			t.Fatal(err)
		}
		histRows = append(histRows, []any{u, e, resolved})
	}
	rows.Close()
	if !reflect.DeepEqual(normalizeRows(histRows),
		normalizeRows(g.Probes.RetryQueue.HistoryRows)) {
		t.Errorf("history rows = %v; golden %v", histRows,
			g.Probes.RetryQueue.HistoryRows)
	}

	// -- the quarantine battery --
	db = newTestCacheDB(t)
	q := g.Probes.Quarantine
	var counts []int64
	for i := 0; i < DeadLinkThreshold; i++ {
		counts = append(counts,
			int64(db.Record404("https://github.com/patient/repo",
				"404 Not Found")))
	}
	if !reflect.DeepEqual(counts, q.Counts) {
		t.Errorf("counts = %v; golden %v", counts, q.Counts)
	}
	if got := db.IsDeadLink("https://github.com/patient/repo",
		0); got != q.PatientDead {
		t.Errorf("patient dead = %v; golden %v", got, q.PatientDead)
	}
	if got := db.IsDeadLink("https://github.com/patient/repo",
		5); got == q.PatientNotDeadAt5 {
		t.Errorf("patient dead at 5 = %v; golden not-dead=%v", got,
			q.PatientNotDeadAt5)
	}
	if got := len(db.GetDeadURLs(5)); int64(got) != 0 {
		t.Errorf("dead urls at 5 = %d; golden %v", got, q.DeadURLsAt5)
	}
	db.Record404("https://github.com/o/one", "404 Not Found")
	db.Record404("https://github.com/o/two", "404 Not Found")
	db.Record404("https://github.com/o/two", "404 Not Found")
	db.ConfirmDead("https://github.com/o/gone", "x", 3)
	for i := 0; i < 4; i++ {
		db.Record404("https://github.com/o/high", "404 Not Found")
	}
	unconf := map[string]int64{}
	for _, r := range db.GetUnconfirmed404s(3) {
		unconf[r.URL] = r.FailCount
	}
	if !reflect.DeepEqual(unconf, q.Unconfirmed) {
		t.Errorf("unconfirmed = %v; golden %v", unconf, q.Unconfirmed)
	}
	if got := db.IsDeadLink("https://github.com/o/high", 4); got != q.HighNeverLowered {
		t.Errorf("high never lowered = %v; golden %v", got, q.HighNeverLowered)
	}
	var allDecom [][]any
	for _, r := range db.GetAllDecommissioned() {
		allDecom = append(allDecom, []any{r.URL, r.Error})
	}
	if !reflect.DeepEqual(normalizeRows(allDecom),
		normalizeRows(q.AllDecommissioned)) {
		t.Errorf("all decommissioned = %v; golden %v", allDecom,
			q.AllDecommissioned)
	}

	// -- purge_old + the processed-row helpers --
	db = newTestCacheDB(t)
	if err := db.AddProcessed(1, "https://github.com/o/fresh", "o",
		"fresh", "n1.md", "AI"); err != nil {
		t.Fatal(err)
	}
	if err := db.AddProcessed(2, "https://github.com/o/ancient", "o",
		"ancient", "n2.md", "AI"); err != nil {
		t.Fatal(err)
	}
	db.Lock()
	_, err = db.SQL().Exec(
		"UPDATE processed_repos SET last_checked = '2020-01-01T00:00:00'" +
			" WHERE repo_id = 2")
	db.Unlock()
	if err != nil {
		t.Fatal(err)
	}
	if err := db.PurgeOld(6); err != nil {
		t.Fatal(err)
	}
	pg := g.Probes.PurgeOld
	var leftIDs []int64
	db.RLock()
	rows, err = db.SQL().Query(
		"SELECT repo_id FROM processed_repos ORDER BY repo_id")
	db.RUnlock()
	if err != nil {
		t.Fatal(err)
	}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			t.Fatal(err)
		}
		leftIDs = append(leftIDs, id)
	}
	rows.Close()
	if !reflect.DeepEqual(leftIDs, pg.LeftRepoIDs) {
		t.Errorf("purge left = %v; golden %v", leftIDs, pg.LeftRepoIDs)
	}
	if dup, err := db.IsDuplicate(1); err != nil || dup != pg.StillDup {
		t.Errorf("still duplicate = %v/%v", dup, err)
	}
	if dup, err := db.IsDuplicate(2); err != nil || dup == pg.AncientGone {
		t.Errorf("ancient gone = %v/%v", dup, err)
	}
	np, nperr := db.GetNotePath(1)
	if nperr != nil || (np == nil) != (pg.NotePath == nil) {
		t.Errorf("note path = %v; golden %v", np, pg.NotePath)
	} else if np != nil && *np != *pg.NotePath {
		t.Errorf("note path = %q; golden %q", *np, *pg.NotePath)
	}
	row := db.ProcessedRowFor("https://github.com/o/fresh")
	if row == nil {
		t.Fatal("row_for = nil")
	}
	if got := *row.NotePath; got != "n1.md" {
		t.Errorf("row_for note_path = %q", got)
	}
	if got := db.ForgetProcessedURL(
		"https://github.com/o/fresh"); got != pg.Forget {
		t.Errorf("forget = %v; golden %v", got, pg.Forget)
	}
	if got := db.ForgetProcessedURL(
		"https://github.com/o/fresh"); got != pg.ForgetAgain {
		t.Errorf("forget again = %v; golden %v", got, pg.ForgetAgain)
	}

	// -- decommission's legacy shape across a reopen --
	dir := t.TempDir()
	path = filepath.Join(dir, "cache.db")
	db, err = NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	db.Decommission("https://github.com/legacy/gone", "404 Not Found")
	db.Close()
	db, err = NewCacheDB(path)
	if err != nil {
		t.Fatal(err)
	}
	dl := g.Probes.DecommissionLegacy
	if got := db.IsDecommissioned(
		"https://github.com/legacy/gone"); got != dl.IsDecommissioned {
		t.Errorf("is_decommissioned = %v; golden %v", got, dl.IsDecommissioned)
	}
	var reasonRows [][]any
	for _, r := range db.GetAllDecommissioned() {
		reasonRows = append(reasonRows, []any{r.URL, r.Error})
	}
	if !reflect.DeepEqual(normalizeRows(reasonRows),
		normalizeRows(dl.ReasonRows)) {
		t.Errorf("reason rows = %v; golden %v", reasonRows, dl.ReasonRows)
	}
	if got := db.ResetDeadLinks(""); int64(got) != dl.ResetAll {
		t.Errorf("reset all = %d; golden %d", got, dl.ResetAll)
	}
	if got := len(db.GetDeadURLSet(0)); got != len(dl.EmptyAfter) {
		t.Errorf("empty after = %d; golden %d", got, len(dl.EmptyAfter))
	}
	db.Close()
}

// ---------------------------------------------------------------------------
// THE T-24 ACCEPTANCE — the port opens T-20's Python-created fixture
// and every getter answers byte-exactly; Go writes survive; record_404
// fails closed.
// ---------------------------------------------------------------------------

func TestCacheDBOpensPythonCreatedFixture(t *testing.T) {
	g := loadFixtureGolden(t)
	src := filepath.Join("testdata", "cache_python_created.db")

	// The atomic-pair tie (T-20's law, re-asserted here).
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if got := sha256Hex(data); got != g.FixtureSha256 {
		t.Fatalf("fixture sha256 = %s; golden records %s", got, g.FixtureSha256)
	}

	work := filepath.Join(t.TempDir(), "cache_python_created.db")
	if err := os.WriteFile(work, data, 0o644); err != nil {
		t.Fatal(err)
	}
	db, err := NewCacheDB(work)
	if err != nil {
		t.Fatalf("open Python-created fixture: %v", err)
	}
	defer db.Close()

	// The getters over the reference's own rows — byte-exact answers.
	// add_processed(111, one) was INSERT OR REPLACEd by (111, one-v2):
	// TWO rows survive (111 + 222).
	if urls := db.GetAllProcessedURLs(); len(urls) != 2 {
		t.Fatalf("all processed urls = %v", urls)
	}
	row := db.ProcessedRowFor("https://github.com/owner/one-v2")
	if row == nil || row.RepoID != 111 || strOr(row.URL) !=
		"https://github.com/owner/one-v2" {
		t.Fatalf("processed_row_for(one-v2) = %+v", row)
	}
	if row := db.ProcessedRowFor(
		"https://github.com/owner/never-processed"); row != nil {
		t.Fatalf("never-processed row = %+v", row)
	}
	failed := db.GetFailedURLs()
	if len(failed) != 2 { // fail1 unresolved + fail3's second failure
		t.Fatalf("failed urls = %+v", failed)
	}
	if got := db.GetFailedCount(); got != 2 {
		t.Fatalf("failed count = %d", got)
	}
	// dead1 has 2 strikes (unconfirmed), dead3 confirmed at 3.
	if db.IsDeadLink("https://github.com/owner/dead1", 0) {
		t.Fatal("dead1 (2 strikes) read as dead")
	}
	if !db.IsDeadLink("https://github.com/owner/dead3", 0) {
		t.Fatal("dead3 (confirm_dead) not dead")
	}
	// The CAST-law columns: decommissioned_at through GetDeadURLs /
	// GetQuarantineStats must carry Python's raw isoformat bytes (the
	// auto-timespec shape: fraction iff microseconds != 0).
	for _, r := range db.GetQuarantineStats() {
		if r.DecommissionedAt != nil && !pyAutoShape(*r.DecommissionedAt) {
			t.Errorf("decommissioned_at %q is not the Python auto shape "+
				"(the CAST read law is live here)", *r.DecommissionedAt)
		}
	}
	// GitHub normalize_url lowercases the DOMAIN only — the case-drifted
	// path spelling is a DISTINCT key (the golden's settled set carries
	// both rows; only the trailing slash folds).
	if got := db.SettledReposCount(); got != 2 {
		t.Fatalf("settled count = %d; want 2 (the golden's answer)", got)
	}
	if !db.IsRepoSettled("https://github.com/owner/one") ||
		!db.IsRepoSettled("https://github.com/OWNER/one/") {
		t.Fatal("the normalized dedupe keying drifted")
	}
	if v := db.GetMeta("probe_key"); v == nil || *v != "probe-value" {
		t.Fatalf("meta = %v", v)
	}
	if v := db.GetMeta("unicode_key"); v == nil || *v != "näive — 测试" {
		t.Fatalf("unicode meta = %v", v)
	}

	// THE READ/WRITE PROBE: a Go write survives close+reopen next to
	// the Python rows, in the same shapes.
	if err := db.AddProcessed(999, "https://github.com/go/write",
		"go", "write", "Go Write/n.md", "AI"); err != nil {
		t.Fatal(err)
	}
	db.Record404("https://github.com/go/dead", "404 Not Found")
	if _, err := db.SettleRepos([]string{"https://github.com/go/settled"}); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}
	db2, err := NewCacheDB(work)
	if err != nil {
		t.Fatal(err)
	}
	defer db2.Close()
	np, err := db2.GetNotePath(999)
	if err != nil || np == nil || *np != "Go Write/n.md" {
		t.Fatalf("go row after reopen = %v/%v", np, err)
	}
	// Go-written processed_at keeps the auto-timespec shape.
	db2.RLock()
	var ts sql.NullString
	err = db2.SQL().QueryRow(
		"SELECT CAST(processed_at AS TEXT) FROM processed_repos" +
			" WHERE repo_id = 999").Scan(&ts)
	db2.RUnlock()
	if err != nil || !ts.Valid {
		t.Fatalf("go processed_at read: %v", err)
	}
	if !pyAutoShape(ts.String) {
		t.Fatalf("go-written processed_at %q is not the auto shape", ts.String)
	}
	if got := db2.Record404("https://github.com/go/dead",
		"404 Not Found"); got != 2 {
		t.Fatalf("go 404 count after reopen = %d; want 2", got)
	}
	if !db2.IsRepoSettled("https://github.com/go/settled") {
		t.Fatal("go-settled row lost")
	}
	// and the Python rows are untouched
	if row := db2.ProcessedRowFor("https://github.com/owner/one-v2"); row == nil ||
		strOr(row.NotePath) != "AI & ML/owner one v2.md" {
		t.Fatalf("python row after go writes = %+v", row)
	}

	// record_404 FAILS CLOSED on a closed connection (the acceptance).
	db2.Close()
	if got := db2.Record404("https://github.com/closed/db",
		"404 Not Found"); got != DeadLinkThreshold {
		t.Fatalf("fail-closed record_404 = %d; want %d", got, DeadLinkThreshold)
	}
}

// ---------------------------------------------------------------------------
// Small helpers.
// ---------------------------------------------------------------------------

func stringsContains(s, sub string) bool {
	return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
		containsSub(s, sub))
}

func containsSub(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

func strOr(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

// pyAutoShape checks the datetime.now().isoformat() auto-timespec
// shape: YYYY-MM-DDTHH:MM:SS with a 1-6 digit fraction IFF nonzero.
func pyAutoShape(s string) bool {
	if len(s) < 19 {
		return false
	}
	if _, err := time.Parse("2006-01-02T15:04:05", s[:19]); err != nil {
		return false
	}
	if len(s) == 19 {
		return true
	}
	if s[19] != '.' {
		return false
	}
	frac := s[20:]
	if len(frac) < 1 || len(frac) > 6 {
		return false
	}
	for _, c := range frac {
		if c < '0' || c > '9' {
			return false
		}
	}
	// a fraction of all zeros would not be emitted by the auto shape
	for _, c := range frac {
		if c != '0' {
			return true
		}
	}
	return false
}

func settleReposMap(r SettleReposReport) map[string]any {
	return map[string]any{
		"settled": int64(r.Settled), "retries_cleared": int64(r.RetriesCleared),
		"already": r.Already,
	}
}

func normAnyMap(m map[string]any) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = pyNumber(v)
	}
	return out
}

// strSlicesEqual treats nil and empty as equal (JSON decoding makes
// empty lists non-nil; the classifier returns nil for absent buckets).
func strSlicesEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func sortInt64(s []int64) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// pyInt normalizes a decoded golden number (dec.UseNumber keeps
// json.Number).
func pyInt(v any) int64 {
	switch x := v.(type) {
	case json.Number:
		i, _ := x.Int64()
		return i
	case int64:
		return x
	case int:
		return int64(x)
	case float64:
		return int64(x)
	}
	return -1
}
